import { type SynapseEnhancedHttpClient } from "./utils/http.ts";
import type { IFriend, IFriendCategory, IFriendRequest, IBlockedUser, IPaginationParams } from "./models/types.ts";

export type MockHttpClient = jest.Mocked<SynapseEnhancedHttpClient> & {
    setResponse: <T>(data: T) => void;
};

export interface MockResponse<T> {
    data: T;
    status: number;
}

export function createMockHttpClient(): MockHttpClient {
    const mock = {
        request: jest.fn(),
        setResponse: jest.fn(),
    } as unknown as MockHttpClient;
    return mock;
}

export function createMockHttpClientInstance(): MockHttpClient {
    return createMockHttpClient();
}

export function createMockFriend(overrides?: Partial<IFriend>): IFriend {
    return {
        friend_id: `@user${Math.random().toString(36).substring(7)}:example.com`,
        display_name: "Test User",
        avatar_url: "mxc://example.com/avatar",
        status: "accepted",
        created_at: new Date().toISOString(),
        category_id: "default",
        ...overrides,
    };
}

export function createMockFriendList(count: number = 10): IFriend[] {
    return Array.from({ length: count }, (_, i) =>
        createMockFriend({
            friend_id: `@user${i}:example.com`,
            display_name: `Test User ${i}`,
        }),
    );
}

export function createMockFriendCategory(overrides?: Partial<IFriendCategory>): IFriendCategory {
    return {
        id: `category_${Math.random().toString(36).substring(7)}`,
        name: "Test Category",
        created_at: new Date().toISOString(),
        friend_count: 0,
        ...overrides,
    };
}

export function createMockFriendRequest(overrides?: Partial<IFriendRequest>): IFriendRequest {
    return {
        request_id: `request_${Math.random().toString(36).substring(7)}`,
        requester_id: `@user${Math.random().toString(36).substring(7)}:example.com`,
        target_id: `@user${Math.random().toString(36).substring(7)}:example.com`,
        status: "pending",
        message: "Hi, I'd like to be friends!",
        created_at: new Date().toISOString(),
        ...overrides,
    };
}

export function createMockFriendRequestList(count: number = 5): IFriendRequest[] {
    return Array.from({ length: count }, (_, i) =>
        createMockFriendRequest({
            request_id: `request_${i}`,
            requester_id: `@user${i}:example.com`,
            target_id: `@user${i + 1}:example.com`,
        }),
    );
}

export function createMockBlockedUser(overrides?: Partial<IBlockedUser>): IBlockedUser {
    return {
        user_id: `@user${Math.random().toString(36).substring(7)}:example.com`,
        display_name: "Blocked User",
        blocked_at: new Date().toISOString(),
        reason: "Spam",
        ...overrides,
    };
}

export function createMockPaginationParams(overrides?: Partial<IPaginationParams>): IPaginationParams {
    return {
        page: 1,
        limit: 20,
        ...overrides,
    };
}

export function createMockSuccessResponse<T>(data: T): MockResponse<T> {
    return {
        data,
        status: 200,
    };
}

export function createMockErrorResponse(
    message: string,
    status: number = 500,
): MockResponse<{ status: string; error: string }> {
    return {
        data: {
            status: "error",
            error: message,
        },
        status,
    };
}

export function setupMockRequest<T>(mock: jest.Mock, data: T): void {
    mock.mockResolvedValue(createMockSuccessResponse(data));
}

export function setupMockError(mock: jest.Mock, message: string, status: number = 500): void {
    mock.mockResolvedValue(createMockErrorResponse(message, status));
}
